// Validate the inbound contract and mint a content_id. Never throws: an invalid
// body still has to come back as a 200 with a valid scorecard shape.
const crypto = require('crypto');
const b = $input.first().json.body ?? $input.first().json ?? {};
const c = b.content || {};

const text = [c.body, c.caption, c.hook].filter(Boolean).join('\n').trim();
const id = crypto.createHash('sha1')
  .update(`${b.creator_handle || 'unknown'}|${c.video_url || text}`)
  .digest('hex').slice(0, 16);

const errs = [];
if (!b.creator_handle) errs.push('creator_handle missing');
if (!['text', 'video_url', 'transcript'].includes(c.type)) errs.push('content.type invalid');
if (c.type === 'video_url' && !c.video_url) errs.push('video_url missing');
if (c.type !== 'video_url' && !text) errs.push('no scoreable text');

return [{ json: {
  content_id: id,
  iteration: Number.isFinite(+b.iteration) ? +b.iteration : 0,
  creator_handle: b.creator_handle || 'unknown',
  content: { type: c.type || 'text', hook: c.hook ?? null, body: c.body ?? null,
             video_url: c.video_url ?? null, caption: c.caption ?? null },
  candidate_text: text,
  candidate_hook: c.hook || '',
  candidate_caption: c.caption || '',
  input_errors: errs,
  degraded: [],
}}];

// Wizper returns { text, chunks, languages }. If it produced nothing usable we fall
// back to caption + hook and record "transcript" in degraded - per spec §6.
const src = $('Normalize Input').first().json;
const t = String($input.first().json.text || '').trim();

const out = { ...src };
if (t) {
  out.candidate_text = t;
} else {
  out.candidate_text = [src.candidate_caption, src.candidate_hook].filter(Boolean).join('\n').trim();
  out.degraded = [...(src.degraded || []), 'transcript'];
}
return [{ json: out }];

// The backend may not be up (it is not reachable from n8n Cloud at all during the
// hackathon). Fall back to the committed fixture and record the degraded axis, so the
// run still returns a real score instead of dying. Spec §6.
const FIXTURE = {
"creator_handle": "chaosadam13",
"fingerprint_version": 1,
"voice_traits": [
{
"trait": "Opens on an unresolved question rather than a claim",
"evidence": "So why does nobody talk about this?",
"strength": 0.78
},
{
"trait": "Self-deprecating aside within the first 15 seconds",
"evidence": "and yes, I got this wrong for two years",
"strength": 0.61
},
{
"trait": "Concrete numbers over adjectives",
"evidence": "it cut the run from 40 minutes to 90 seconds",
"strength": 0.72
},
{
"trait": "Short declarative closers, no call-to-action stacking",
"evidence": "That's it. That's the whole trick.",
"strength": 0.55
}
],
"hook_archetypes": [
{
"name": "question_cold_open",
"pattern": "Interrogative first sentence, no context given",
"example": "Why is your build still taking nine minutes?"
},
{
"name": "confession",
"pattern": "Admit a personal failure, then generalise",
"example": "I shipped this broken for a month."
}
],
"pacing": {
"rhythm_description": "Short sentence, short sentence, long explanatory sentence. Repeats in threes.",
"opener_style": "Question, then a two-beat pause before context",
"closer_style": "Two words to four words. Full stop. No outro."
},
"vocabulary": {
"signature_phrases": [
"here's the thing",
"that's the whole trick",
"nobody talks about",
"two years of this"
],
"register": "casual-technical",
"formality": 0.25
},
"taboos": [
{
"rule": "Never open with 'In today's fast-paced world'",
"reason": "Generic AI cadence, creator has mocked it on camera"
},
{
"rule": "No 'smash that like button' or subscribe begging",
"reason": "Creator explicitly refuses CTA stacking"
},
{
"rule": "No em-dash-heavy listicle scaffolding",
"reason": "Reads as LinkedIn copy, off-brand"
}
],
"exemplars": [
{
"excerpt": "Why is your build still taking nine minutes? Mine was too. Then I found out the cache key was being invalidated by a timestamp nobody remembered adding.",
"why_representative": "Question cold-open, concrete number, confession, technical payoff"
},
{
"excerpt": "That's it. That's the whole trick.",
"why_representative": "Canonical closer"
}
]
};

const src = $('Merge Transcript').first().json;
const got = $input.first().json;
const ok = got && !got.error && got.voice_traits;

const degraded = [...(src.degraded || [])];
if (!ok) degraded.push('voice_match');

return [{ json: {
  content_id: src.content_id,
  iteration: src.iteration,
  creator_handle: src.creator_handle,
  candidate_text: src.candidate_text || '',
  candidate_hook: src.candidate_hook || '',
  candidate_caption: src.candidate_caption || '',
  input_errors: src.input_errors || [],
  degraded,
  fingerprint: ok ? got : FIXTURE,
  used_fixture: !ok,
} }];

// The backend may not be up (it is not reachable from n8n Cloud at all during the
// hackathon). Fall back to the committed fixture and record the degraded axis, so the
// run still returns a real score instead of dying. Spec §6.
const FIXTURE = {
"built_at": "2026-07-25T00:00:00Z",
"niche": "developer-tooling",
"trend_cards": [
{
"id": "cold_open_claim",
"pattern": "Hard cold-open claim in the first 2 seconds, no question, no preamble",
