]
};

const src = $('Merge Transcript').first().json;
const got = $input.first().json;
const ok = got && !got.error && got.trend_cards;

const degraded = [...(src.degraded || [])];
if (!ok) degraded.push('trend_align');

return [{ json: {
  content_id: src.content_id,
  iteration: src.iteration,
  creator_handle: src.creator_handle,
  candidate_text: src.candidate_text || '',
  candidate_hook: src.candidate_hook || '',
  candidate_caption: src.candidate_caption || '',
  input_errors: src.input_errors || [],
  degraded,
  trends: ok ? got : FIXTURE,
  used_fixture: !ok,
} }];

// openrouter/router puts the model text in `.output` as a JSON STRING. Strip any fence
// the model added anyway, then parse. A bad parse degrades this axis - it never throws.
const AXIS = 'voice_match';
const src = $('Fingerprint or fixture').first().json;
const raw = $input.first().json;

function parse(s) {
  if (!s) return null;
  let t = String(s).trim().replace(/^```(?:json)?/i, '').replace(/```$/, '').trim();
  const a = t.indexOf('{'), b = t.lastIndexOf('}');
  if (a === -1 || b === -1) return null;
  try { return JSON.parse(t.slice(a, b + 1)); } catch { return null; }
}

const parsed = parse(raw.output);
const degraded = [...(src.degraded || [])];
let result = parsed;

if (!result || typeof result.score !== 'number') {
  degraded.push('voice_match');
  result = { score: 0, dimensions: { vocabulary: 0, pacing: 0, hook_style: 0, register: 0, structure: 0 }, violations: [], reasoning: "Voice scoring unavailable - model returned no parseable JSON." };
}
result.score = Math.max(0, Math.min(100, Number(result.score) || 0));

return [{ json: { ...src, [AXIS]: result, degraded: [...new Set(degraded)] } }];

// openrouter/router puts the model text in `.output` as a JSON STRING. Strip any fence
// the model added anyway, then parse. A bad parse degrades this axis - it never throws.
const AXIS = 'trend_align';
const src = $('Trends or fixture').first().json;
const raw = $input.first().json;

function parse(s) {
  if (!s) return null;
  let t = String(s).trim().replace(/^```(?:json)?/i, '').replace(/```$/, '').trim();
  const a = t.indexOf('{'), b = t.lastIndexOf('}');
  if (a === -1 || b === -1) return null;
  try { return JSON.parse(t.slice(a, b + 1)); } catch { return null; }
}

const parsed = parse(raw.output);
const degraded = [...(src.degraded || [])];
let result = parsed;

if (!result || typeof result.score !== 'number') {
  degraded.push('trend_align');
  result = { score: null, matched_trends: [], missed_opportunities: [], reasoning: "Trend scoring unavailable - model returned no parseable JSON." };
}
result.score = Math.max(0, Math.min(100, Number(result.score) || 0));

return [{ json: { ...src, [AXIS]: result, degraded: [...new Set(degraded)] } }];

// Combine-by-position hands us one item carrying both axes. Guard anyway: this is the
// node where n8n pipelines most often silently lose one side.
const j = $input.first().json;
const v = $('Parse voice').first().json.voice_match || j.voice_match;
const t = $('Parse trend').first().json.trend_align || j.trend_align;

const degraded = [...new Set([
  ...($('Parse voice').first().json.degraded || []),
  ...($('Parse trend').first().json.degraded || []),
])];

// A null trend score (degraded axis) means there is no divergence to reason about.
const divergence = (typeof v?.score === 'number' && typeof t?.score === 'number')
  ? Math.abs(v.score - t.score)
  : 0;

return [{ json: { ...j, voice_match: v, trend_align: t, degraded, divergence } }];

// Tension is non-critical: a failure here returns present:false, never an error. Spec §6.
const src = $('Compute Divergence').first().json;
const raw = $input.first().json;

let t = null;
try {
  let s = String(raw.output || '').trim().replace(/^```(?:json)?/i, '').replace(/```$/, '').trim();
  const a = s.indexOf('{'), b = s.lastIndexOf('}');
  if (a !== -1) t = JSON.parse(s.slice(a, b + 1));
} catch { t = null; }

const tension = (t && t.description)
  ? { present: true, description: t.description || '', example: t.example || '',
      recommendation: t.recommendation || '' }
  : { present: false, description: '', example: '', recommendation: '' };

return [{ json: { ...src, tension } }];

// Build the frozen scorecard.json shape. slop_flags is computed HERE, deliberately
// outside both scoring calls, so generic-AI detection can never contaminate either axis.
const j = $input.first().json;
const text = j.candidate_text || '';

const SLOP = [
  [/in today's (?:fast[- ]paced|digital) world/gi, 'stock_opener', 'high'],
  [/\b(?:it'?s important to note|it'?s worth noting|that said|however,? it)\b/gi, 'hedging_stack', 'medium'],
  [/\b(?:unlock|unleash|elevate|supercharge|revolutionis[ez]e|game[- ]chang(?:er|ing))\b/gi, 'empty_superlative', 'medium'],
  [/\b(?:firstly|secondly|thirdly|in conclusion|to sum up)\b/gi, 'listicle_scaffolding', 'low'],
  [/\b(?:smash that like|hit subscribe|don'?t forget to)\b/gi, 'cta_begging', 'high'],
  [/(\b\w+\b),\s+(\b\w+\b),\s+and\s+(\b\w+\b)\./gi, 'symmetric_tricolon', 'low'],
];

const slop_flags = [];
for (const [re, pattern, severity] of SLOP) {
  const m = text.match(re);
  if (m) slop_flags.push({ pattern, excerpt: String(m[0]).slice(0, 160), severity });
}

const degraded = [...new Set(j.degraded || [])];
if ((j.input_errors || []).length) degraded.push('input');

const voice = j.voice_match || {};
const scorecard = {
  content_id: j.content_id,
  iteration: j.iteration ?? 0,
  voice_match: {
    score: voice.score ?? 0,
    dimensions: {
      vocabulary: voice.dimensions?.vocabulary ?? 0,
      pacing: voice.dimensions?.pacing ?? 0,
      hook_style: voice.dimensions?.hook_style ?? 0,
      register: voice.dimensions?.register ?? 0,
      structure: voice.dimensions?.structure ?? 0,
    },
    violations: Array.isArray(voice.violations) ? voice.violations : [],
    reasoning: voice.reasoning || '',
  },
  trend_align: {
    score: j.trend_align?.score ?? null,
    matched_trends: j.trend_align?.matched_trends || [],
    missed_opportunities: j.trend_align?.missed_opportunities || [],
    reasoning: j.trend_align?.reasoning || '',
  },
  tension: j.tension || { present: false, description: '', example: '', recommendation: '' },
  slop_flags,
  meta: {
    scored_at: new Date().toISOString(),
    fingerprint_version: 1,
    degraded: [...new Set(degraded)],
  },
};

return [{ json: scorecard }];
